/*!
 * SCNU PIONEER — particle emblem
 *
 * The mark is rebuilt as a dot matrix.  Every dot sits on the grid of the
 * original artwork; the pointer acts as a magnet, peeling dots off the mark.
 * Once the pointer moves away they spring back on their own.
 *
 * Data comes from assets/particles.js (generated by tools/extract-particles.py):
 *   grid     number of cells across the square artwork
 *   palette  [[rgb of artwork, rgb used on dark], ...]
 *   data     base64, 4 bytes per cell: gx, gy, colour, coverage
 */
(() => {
  'use strict';

  const DATA = window.SCNU_PARTICLES;
  const canvas = document.getElementById('scene');
  if (!DATA || !canvas || !canvas.getContext) return;

  const ctx = canvas.getContext('2d', { alpha: true });
  if (!ctx) return;

  const CFG = {
    maxSize: 700,     // longest edge of the emblem, css px
    pitch: 7.2,       // wanted distance between dots on screen, css px
    dot: 1.42,        // solid core radius, css px
    halo: 2.15,       // glow radius as a multiple of the core
    influence: 0.34,  // magnet radius as a fraction of the emblem size
    pull: 2.0,        // magnet strength
    swirl: 0.68,      // tangential share of the magnet
    shell: 0.048,     // repel radius as a fraction of the emblem size
    repel: 5.0,       // stops the swarm collapsing into one point
    spring: 0.019,
    damping: 0.9,
    wander: 0.85,
    maxSpeed: 30
  };

  const TAU = Math.PI * 2;
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ------------------------------------------------------------------ data */
  const raw = atob(DATA.data);
  const total = DATA.count;
  const GRID = DATA.grid;
  const COLORS = DATA.palette.map((p) => p[1]);

  const cellX = new Uint8Array(total);
  const cellY = new Uint8Array(total);
  const cellC = new Uint8Array(total);
  const cellV = new Uint8Array(total);
  for (let i = 0; i < total; i++) {
    const o = i << 2;
    cellX[i] = raw.charCodeAt(o);
    cellY[i] = raw.charCodeAt(o + 1);
    cellC[i] = raw.charCodeAt(o + 2);
    cellV[i] = raw.charCodeAt(o + 3);
  }

  /* --------------------------------------------------------------- buffers */
  const unitX = new Float32Array(total); // dot position inside the artwork
  const unitY = new Float32Array(total);
  const homeX = new Float32Array(total); // …and in css pixels
  const homeY = new Float32Array(total);
  const posX = new Float32Array(total);
  const posY = new Float32Array(total);
  const velX = new Float32Array(total);
  const velY = new Float32Array(total);
  const phase = new Float32Array(total);
  const shape = new Uint8Array(total); // palette index
  const seal = new Float32Array(total); // base opacity
  const scale = new Float32Array(total); // dot scale
  const charge = new Float32Array(total); // magnet excitement, 0..1

  let count = 0;
  let stride = 0;

  function hash(n) {
    let x = Math.imul(n ^ 0x9e3779b9, 0x85ebca6b);
    x ^= x >>> 13;
    x = Math.imul(x, 0xc2b2ae35);
    return (x ^ (x >>> 16)) >>> 0;
  }

  function selectCells(step) {
    count = 0;
    for (let i = 0; i < total; i++) {
      if (cellX[i] % step || cellY[i] % step) continue;
      const h = hash(i);
      const jx = ((h & 1023) / 1023 - 0.5) * 0.32;
      const jy = (((h >>> 10) & 1023) / 1023 - 0.5) * 0.32;
      unitX[count] = (cellX[i] + 0.5 + jx) / GRID;
      unitY[count] = (cellY[i] + 0.5 + jy) / GRID;
      shape[count] = cellC[i];
      phase[count] = (((h >>> 20) & 1023) / 1023) * TAU;
      const cover = Math.min(1, (cellV[i] / 255) * 1.4);
      const jitter = 0.9 + (((h >>> 6) & 255) / 255) * 0.1;
      seal[count] = (0.8 + 0.2 * cover) * jitter;
      scale[count] = 0.62 + 0.38 * cover;
      count++;
    }
    stride = step;
  }

  /* --------------------------------------------------------------- layout */
  let vw = 0;
  let vh = 0;
  let dpr = 1;
  let size = 0;
  let midX = 0;
  let midY = 0;
  let sprites = [];
  let dotSize = 0;

  function makeSprite(rgb, coreR, glowR) {
    const c = document.createElement('canvas');
    const s = Math.max(6, Math.ceil(glowR * 2) + 2);
    c.width = s;
    c.height = s;
    const g = c.getContext('2d');
    const m = s / 2;
    const [red, green, blue] = rgb;
    const at = (a) => `rgba(${red},${green},${blue},${a})`;

    const bloom = g.createRadialGradient(m, m, 0, m, m, m);
    bloom.addColorStop(0, at(0.3));
    bloom.addColorStop(0.4, at(0.16));
    bloom.addColorStop(0.72, at(0.04));
    bloom.addColorStop(1, at(0));
    g.fillStyle = bloom;
    g.fillRect(0, 0, s, s);

    g.fillStyle = at(1);
    g.beginPath();
    g.arc(m, m, coreR, 0, TAU);
    g.fill();
    return c;
  }

  function buildSprites() {
    const core = CFG.dot * dpr;
    sprites = COLORS.map((rgb) => makeSprite(rgb, core, core * CFG.halo));
    dotSize = CFG.dot * CFG.halo * 2;
  }

  let placed = false;

  function resize() {
    vw = window.innerWidth;
    vh = window.innerHeight;
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(vw * dpr);
    canvas.height = Math.round(vh * dpr);
    canvas.style.width = vw + 'px';
    canvas.style.height = vh + 'px';

    size = Math.min(vw * 0.8, vh * 0.78, CFG.maxSize);
    midX = vw / 2;
    midY = vh / 2;

    const step = Math.max(1, Math.round((CFG.pitch * GRID) / size));
    const rebuilt = step !== stride;
    if (rebuilt) selectCells(step);

    for (let i = 0; i < count; i++) {
      homeX[i] = midX + (unitX[i] - 0.5) * size;
      homeY[i] = midY + (unitY[i] - 0.5) * size;
      if (!placed) {
        const k = 1.3 + (phase[i] / TAU - 0.5) * 0.26;
        posX[i] = midX + (homeX[i] - midX) * k;
        posY[i] = midY + (homeY[i] - midY) * k;
      } else if (rebuilt) {
        posX[i] = homeX[i];
        posY[i] = homeY[i];
        velX[i] = 0;
        velY[i] = 0;
      }
    }
    placed = true;

    buildSprites();
    if (reduce) draw(performance.now(), 1);
  }

  /* -------------------------------------------------------------- pointer */
  const pointer = { x: 0, y: 0, tx: 0, ty: 0, on: false };

  function movePointer(x, y) {
    pointer.tx = x;
    pointer.ty = y;
    if (!pointer.on) {
      pointer.x = x;
      pointer.y = y;
      pointer.on = true;
    }
  }

  window.addEventListener('pointermove', (e) => movePointer(e.clientX, e.clientY), { passive: true });
  window.addEventListener('pointerdown', (e) => movePointer(e.clientX, e.clientY), { passive: true });
  window.addEventListener('pointerup', (e) => {
    if (e.pointerType !== 'mouse') pointer.on = false;
  }, { passive: true });
  window.addEventListener('pointercancel', () => { pointer.on = false; }, { passive: true });
  document.addEventListener('pointerleave', () => { pointer.on = false; });
  window.addEventListener('blur', () => { pointer.on = false; });

  /* ---------------------------------------------------------------- frame */
  let last = 0;
  let boot = 0;
  let running = false;
  let frameId = 0;

  function step(now) {
    const dt = Math.min(2.2, Math.max(0.25, (now - last) / 16.6667));
    last = now;

    const ease = 1 - Math.pow(0.78, dt);
    pointer.x += (pointer.tx - pointer.x) * ease;
    pointer.y += (pointer.ty - pointer.y) * ease;

    const damp = Math.pow(CFG.damping, dt);
    const spring = CFG.spring * dt;
    const magnet = size * CFG.influence;
    const magnet2 = magnet * magnet;
    const shell = size * CFG.shell;
    const clock = now * 0.00055;
    const amp = CFG.wander;
    const maxV = CFG.maxSpeed;
    const boost = 1 + Math.max(0, 1 - (now - boot) / 1100) * 2.4;

    for (let i = 0; i < count; i++) {
      const x = posX[i];
      const y = posY[i];
      const a = clock + phase[i];

      let ax = (homeX[i] + Math.cos(a) * amp - x) * spring * boost;
      let ay = (homeY[i] + Math.sin(a * 1.7) * amp - y) * spring * boost;
      let hot = 0;

      if (pointer.on) {
        let dx = pointer.x - x;
        let dy = pointer.y - y;
        const d2 = dx * dx + dy * dy;
        if (d2 < magnet2) {
          const d = Math.sqrt(d2) + 0.001;
          const t = 1 - d / magnet;
          const f = t * t * CFG.pull;
          hot = t;
          dx /= d;
          dy /= d;
          ax += dx * f - dy * f * CFG.swirl;
          ay += dy * f + dx * f * CFG.swirl;
          if (d < shell) {
            const r = 1 - d / shell;
            const rf = r * r * CFG.repel;
            ax -= dx * rf;
            ay -= dy * rf;
          }
        }
      }
      charge[i] += (hot - charge[i]) * 0.14;

      let vx = (velX[i] + ax * dt) * damp;
      let vy = (velY[i] + ay * dt) * damp;
      const speed = Math.sqrt(vx * vx + vy * vy);
      if (speed > maxV) {
        vx = (vx / speed) * maxV;
        vy = (vy / speed) * maxV;
      }
      velX[i] = vx;
      velY[i] = vy;
      posX[i] = x + vx * dt;
      posY[i] = y + vy * dt;
    }
  }

  function draw(now, force) {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, vw, vh);
    ctx.globalCompositeOperation = 'source-over';

    const elapsed = now - boot;
    let alpha = -1;

    for (let i = 0; i < count; i++) {
      let a = seal[i] * (1 + charge[i] * 0.75);
      if (a > 1) a = 1;
      if (!force) {
        const fade = (elapsed - phase[i] * 26) / 620;
        if (fade <= 0) continue;
        if (fade < 1) a *= fade;
      }
      const s = dotSize * scale[i] * (1 + charge[i] * 0.35);
      if (a !== alpha) {
        alpha = a;
        ctx.globalAlpha = a;
      }
      ctx.drawImage(sprites[shape[i]], posX[i] - s * 0.5, posY[i] - s * 0.5, s, s);
    }
    ctx.globalAlpha = 1;
  }

  function loop(now) {
    frameId = requestAnimationFrame(loop);
    step(now);
    draw(now, false);
  }

  function start() {
    if (running) return;
    running = true;
    last = performance.now();
    if (!boot) boot = last + 80;
    frameId = requestAnimationFrame(loop);
  }

  function stop() {
    running = false;
    cancelAnimationFrame(frameId);
  }

  /* ----------------------------------------------------------------- boot */
  resize();
  window.addEventListener('resize', resize, { passive: true });
  window.addEventListener('orientationchange', resize, { passive: true });
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) stop();
    else start();
  });

  if (reduce) draw(performance.now(), 1);
  else start();
})();
